+func classifyFile(oldPath, newPath, name string) {
+	oldFile, err := os.Open(oldPath)
+	if err != nil {
+		panic(err)
+	}
+	defer oldFile.Close()
+	newFile, err := os.Open(newPath)
+	if err != nil {
+		panic(err)
+	}
+	defer newFile.Close()
+	oldScan, newScan := bufio.NewScanner(oldFile), bufio.NewScanner(newFile)
+	oldScan.Buffer(make([]byte, 64*1024), 4*1024*1024)
+	newScan.Buffer(make([]byte, 64*1024), 4*1024*1024)
