+		}
+		prefix := commonPrefix(oldLine, newLine)
+		suffix := commonSuffix(oldLine[prefix:], newLine[prefix:])
+		oldEnd, newEnd := len(oldLine)-suffix, len(newLine)-suffix
+		oldSpan, newSpan := oldLine[prefix:oldEnd], newLine[prefix:newEnd]
+		contextStart := max(0, prefix-240)
