+
+func nearestKey(context string) string {
+	if matches := assignmentKey.FindStringSubmatch(context); len(matches) == 2 {
+		return matches[1]
+	}
+	if matches := jsonKey.FindStringSubmatch(context); len(matches) == 2 {
+		return matches[1]
+	}
+	return "unknown"
+}
+
+func shape(value string) string {
+	trimmed := strings.Trim(value, `"'`)
+	kinds := make(map[string]bool)
+	for _, r := range trimmed {
+		switch {
+		case unicode.IsLetter(r):
+			kinds["letters"] = true
+		case unicode.IsDigit(r):
+			kinds["digits"] = true
+		case r == '_' || r == '-' || r == '.':
+			kinds["separators"] = true
+		case unicode.IsSpace(r):
+			kinds["space"] = true
+		default:
+			kinds["symbols"] = true
+		}
+	}
+	return fmt.Sprintf("len=%d call=%t member=%t quoted=%t kinds=%v", len(trimmed), codeCall.MatchString(trimmed), memberRef.MatchString(trimmed), len(value) != len(trimmed), kinds)
